//! The generated pages of the book.

use sl_config::{Config, Env};
use sl_core::{Date, FixKind, Level, LintMeta, Need, Source, ToolUse};
use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::Path;

/// The marker lines around the generated nav in `zensical.toml`
pub const NAV_BEGIN: &str =
    "# spirit-level:book-nav (generated by `spirit-level book`, do not edit by hand)";
/// The end marker
pub const NAV_END: &str = "# spirit-level:book-nav-end";

/// The hand-written pages, in nav order: (title, path)
pub const HAND_PAGES: &[(&str, &str)] = &[
    ("Introduction", "index.md"),
    ("Getting started", "start.md"),
    ("Configuration", "configuration.md"),
    ("The crate map", "map.md"),
    ("Waivers", "waivers.md"),
    ("Output and exit codes", "output.md"),
    ("External tools", "tools.md"),
    ("Writing a lint", "writing-lints.md"),
];

/// The level and reason of every lint in every shipped tier (each tier resolved with what it extends), in the
/// order of `spirit_level::TIERS`; an error names a shipped tier that does not resolve
pub fn tier_levels() -> Result<Vec<(&'static str, Config)>, String> {
    let lints = spirit_level::lints();
    spirit_level::TIERS
        .iter()
        .map(|(name, _)| {
            let env = Env {
                lints: &lints,
                tier: &spirit_level::tier,
                today: Date {
                    year: 2000,
                    month: 1,
                    day: 1,
                },
                version: None,
            };
            Config::from_tiers(&[name], &env)
                .map(|c| (*name, c))
                .map_err(|e| format!("shipped tier {name} does not resolve: {e:?}"))
        })
        .collect()
}

/// Every generated file: path relative to the docs dir, and its text
pub fn pages() -> Result<BTreeMap<String, String>, String> {
    let lints = spirit_level::lints();
    let tiers = tier_levels()?;
    let mut out = BTreeMap::new();
    for m in &lints {
        out.insert(format!("lints/{}.md", m.id), lint_page(m, &tiers));
    }
    out.insert("lints/index.md".into(), lints_index(&lints, &tiers));
    for ((name, text), (_, c)) in spirit_level::TIERS.iter().zip(&tiers) {
        out.insert(format!("tiers/{name}.md"), tier_page(name, text, c, &lints));
    }
    out.insert("tiers/index.md".into(), tiers_index());
    Ok(out)
}

fn source(m: &LintMeta) -> String {
    match m.source {
        Source::Native => "spirit_level".into(),
        Source::Tool { name, r#use } => format!(
            "{name} ({})",
            match r#use {
                ToolUse::Library => "linked as a library",
                ToolUse::Executable => "run as an executable",
            }
        ),
    }
}

fn need(n: &Need) -> String {
    match n {
        Need::Resolve => "the resolved dependency graph (full `cargo metadata`)".into(),
        Need::Map => "the crate map ([map] or map-file)".into(),
        Need::Tool(t) => format!("`{t}` installed"),
        Need::Nightly => "a nightly toolchain".into(),
        Need::Elf => "the firmware's linked ELF (`--elf`)".into(),
    }
}

fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

/// One lint's page
pub fn lint_page(m: &LintMeta, tiers: &[(&str, Config)]) -> String {
    let mut s = String::new();
    let _ = writeln!(s, "# {}\n", m.id);
    let _ = writeln!(s, "**Rule:** {}.\n", capital(m.summary));
    let _ = writeln!(s, "| | |\n|---|---|");
    let _ = writeln!(s, "| Category | [{0}](index.md#{0}) |", m.category);
    let _ = writeln!(s, "| Source | {} |", source(m));
    let _ = writeln!(
        s,
        "| Fix | {} |",
        match m.fix {
            FixKind::Exact => "exact: `spirit-level check --fix` applies it",
            FixKind::None => "by hand",
        }
    );
    if !m.needs.is_empty() {
        let n: Vec<String> = m.needs.iter().map(need).collect();
        let _ = writeln!(s, "| Needs | {} |", n.join(", "));
    }
    let _ = writeln!(s, "\n## Level per tier\n");
    let _ = writeln!(s, "| Tier | Level | Reason |\n|---|---|---|");
    for (name, c) in tiers {
        let l = c.lint(m.id);
        let lvl = if l.level == Level::Allow {
            "off".to_string()
        } else {
            format!("`{}`", l.level)
        };
        let _ = writeln!(
            s,
            "| [{name}](../tiers/{name}.md) | {lvl} | {} |",
            cell(&l.reason)
        );
    }
    if !m.params.is_empty() {
        let _ = writeln!(s, "\n## Parameters\n");
        let _ = writeln!(s, "| Name | Type | Default | Meaning |\n|---|---|---|---|");
        for p in m.params {
            let _ = writeln!(
                s,
                "| `{}` | {} | `{}` | {} |",
                p.name,
                p.kind.name(),
                cell(p.default),
                cell(p.doc)
            );
        }
    }
    let _ = writeln!(s, "\n{}\n", m.docs.trim());
    let _ = writeln!(
        s,
        "## Configure\n\n```toml\n[lints.{}]\nlevel = \"deny\"",
        m.id
    );
    for p in m.params {
        let _ = writeln!(s, "{} = {}", p.name, p.default);
    }
    let _ = writeln!(
        s,
        "reason = \"why this project wants it at this level\"\n```"
    );
    let _ = writeln!(
        s,
        "\nAllow one finding in the code with `// spirit-level: allow({}) <reason>` ([waivers](../waivers.md)).",
        m.id
    );
    s
}

fn capital(s: &str) -> String {
    let mut c = s.chars();
    c.next().map_or_else(String::new, |f| {
        f.to_uppercase().collect::<String>() + c.as_str()
    })
}

fn lints_index(lints: &[&LintMeta], tiers: &[(&str, Config)]) -> String {
    let mut s = String::from(
        "# Lints\n\nEvery lint, grouped by category, with its level in each shipped tier (`off`: the tier does not enable it). A project changes any of them in its `spirit_level.toml` ([configuration](../configuration.md)).\n",
    );
    let mut cats: BTreeMap<&str, Vec<&LintMeta>> = BTreeMap::new();
    for m in lints {
        cats.entry(m.category).or_default().push(m);
    }
    for (cat, ms) in cats {
        let _ = writeln!(s, "\n## {cat}\n");
        let mut head = String::from("| Lint | Rule |");
        let mut sep = String::from("|---|---|");
        for (n, _) in tiers {
            let _ = write!(head, " {n} |");
            sep.push_str("---|");
        }
        let _ = writeln!(s, "{head}\n{sep}");
        let mut ms = ms;
        ms.sort_by_key(|m| m.id);
        for m in ms {
            let mut row = format!("| [{0}]({0}.md) | {1} |", m.id, cell(m.summary));
            for (_, c) in tiers {
                let l = c.lint(m.id).level;
                let _ = write!(
                    row,
                    " {} |",
                    if l == Level::Allow { "off" } else { l.name() }
                );
            }
            let _ = writeln!(s, "{row}");
        }
    }
    s
}

fn tier_page(name: &str, text: &str, c: &Config, lints: &[&LintMeta]) -> String {
    let mut s = format!(
        "# {name}\n\n{}.\n\n",
        capital(&spirit_level::tier_description(text))
    );
    let ext: Vec<&str> = text
        .lines()
        .find_map(|l| l.trim().strip_prefix("extends = "))
        .map(|e| vec![e.trim_matches('"')])
        .unwrap_or_default();
    if let Some(e) = ext.first() {
        let _ = writeln!(
            s,
            "Extends [{e}]({e}.md): everything below is on top of it.\n"
        );
    }
    let _ = writeln!(
        s,
        "Use it with `extends = \"{name}\"` in `spirit_level.toml`.\n"
    );
    let _ = writeln!(
        s,
        "## Lints enabled (with what it extends)\n\n| Lint | Level | Reason | Set in |\n|---|---|---|---|"
    );
    let mut ids: Vec<&LintMeta> = lints.to_vec();
    ids.sort_by_key(|m| m.id);
    for m in ids {
        let l = c.lint(m.id);
        if l.level == Level::Allow {
            continue;
        }
        let at = l.origin.as_ref().map_or(String::new(), |o| {
            o.file.trim_start_matches("tier:").to_string()
        });
        let _ = writeln!(
            s,
            "| [{0}](../lints/{0}.md) | `{1}` | {2} | {3} |",
            m.id,
            l.level,
            cell(&l.reason),
            at
        );
    }
    let _ = writeln!(s, "\n## The file\n\n```toml\n{}\n```", text.trim());
    s
}

fn tiers_index() -> String {
    let mut s = String::from(
        "# Tiers\n\nA tier is a TOML file of lints shipped with spirit_level. Each size tier extends the one before it; a project picks one with `extends` and adds its own settings on top. Tiers that stand beside the size tiers (like `embedded` and `ai`) are combined with one: `extends = [\"small\", \"embedded\"]`.\n\n| Tier | What it is for |\n|---|---|\n",
    );
    for (n, t) in spirit_level::TIERS {
        let _ = writeln!(
            s,
            "| [{n}]({n}.md) | {} |",
            cell(&spirit_level::tier_description(t))
        );
    }
    s
}

/// The nav block for `zensical.toml`
pub fn nav() -> String {
    let mut s = format!("{NAV_BEGIN}\nnav = [\n");
    for (t, p) in HAND_PAGES {
        let _ = writeln!(s, "    {{ {t:?} = {p:?} }},");
    }
    let _ = writeln!(s, "    {{ \"Tiers\" = [\n        \"tiers/index.md\",");
    for (n, _) in spirit_level::TIERS {
        let _ = writeln!(s, "        \"tiers/{n}.md\",");
    }
    let _ = writeln!(
        s,
        "    ] }},\n    {{ \"Lints\" = [\n        \"lints/index.md\","
    );
    let mut ids: Vec<&str> = spirit_level::lints().iter().map(|m| m.id).collect();
    ids.sort();
    for id in ids {
        let _ = writeln!(s, "        \"lints/{id}.md\",");
    }
    let _ = writeln!(s, "    ] }},\n]\n{NAV_END}");
    s
}

/// Writes (or with `check`, compares) the generated pages under `docs` and the nav in `zensical`; returns the
/// files that differ (written, or stale when checking). Pages of lints that no longer exist are reported too
pub fn write(docs: &Path, zensical: &Path, check: bool) -> std::io::Result<Vec<String>> {
    let mut changed = Vec::new();
    let pages = pages().map_err(std::io::Error::other)?;
    for (rel, text) in &pages {
        let p = docs.join(rel);
        if std::fs::read_to_string(&p).ok().as_deref() != Some(text.as_str()) {
            changed.push(format!("{}", p.display()));
            if !check {
                if let Some(d) = p.parent() {
                    std::fs::create_dir_all(d)?;
                }
                std::fs::write(&p, text)?;
            }
        }
    }
    for dir in ["lints", "tiers"] {
        if let Ok(rd) = std::fs::read_dir(docs.join(dir)) {
            for e in rd.flatten() {
                let rel = format!("{dir}/{}", e.file_name().to_string_lossy());
                if rel.ends_with(".md") && !pages.contains_key(&rel) {
                    changed.push(format!(
                        "{} (no such lint or tier any more)",
                        e.path().display()
                    ));
                    if !check {
                        std::fs::remove_file(e.path())?;
                    }
                }
            }
        }
    }
    let z = std::fs::read_to_string(zensical).unwrap_or_default();
    let new = match (z.find(NAV_BEGIN), z.find(NAV_END)) {
        (Some(a), Some(b)) if b > a => {
            let rest = z[b + NAV_END.len()..]
                .strip_prefix('\n')
                .unwrap_or(&z[b + NAV_END.len()..]);
            format!("{}{}{rest}", &z[..a], nav())
        }
        _ => {
            return Err(std::io::Error::other(format!(
                "{} has no nav markers: put a line `{NAV_BEGIN}` and a line `{NAV_END}` inside its [project] table",
                zensical.display()
            )));
        }
    };
    if new != z {
        changed.push(zensical.display().to_string());
        if !check {
            std::fs::write(zensical, new)?;
        }
    }
    Ok(changed)
}

#[cfg(test)]
mod tests {
    #[test]
    fn writing_twice_changes_nothing() {
        let dir = std::env::temp_dir().join(format!("sl_book_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let z = dir.join("zensical.toml");
        std::fs::write(
            &z,
            format!(
                "[project]\nsite_name = \"x\"\n{}\n{}\n\n[project.theme]\nlanguage = \"en\"\n",
                super::NAV_BEGIN,
                super::NAV_END
            ),
        )
        .unwrap();
        assert!(
            !super::write(&dir.join("docs"), &z, false)
                .unwrap()
                .is_empty()
        );
        assert_eq!(
            super::write(&dir.join("docs"), &z, true).unwrap(),
            Vec::<String>::new()
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}
